from decimal import Decimal


def _source_key(row):
    """Frozen copy of services.erp_corrections.erp_source_key for model values (date/time objects)."""
    amount = round(Decimal(str(row.amount or 0)), 2)
    parts = [
        row.source_currency or "",
        str(row.document_number or ""),
        str(row.invoice_number or ""),
        str(row.authorization_code or ""),
        f"{amount:.2f}",
        row.transaction_date.isoformat() if row.transaction_date else "",
        row.transaction_time.strftime("%H:%M:%S") if row.transaction_time else "",
    ]
    return hashlib.sha1("|".join(parts).encode("utf-8")).hexdigest()


